/**
 * POST /api/v3/webhooks/{webhookId}/duplicate — duplicate a webhook.
 *
 * Thin adapter delegating to @formbricks/integrations/webhooks service.
 */
import { withV3ApiWrapper } from \"@/app/api/v3/lib/api-wrapper\";
import { ZId } from \"@formbricks/types/common\";
import {
  getOrganizationIdFromWebhookId,
  getWorkspaceIdFromWebhookId,
} from \"@/lib/utils/helper\";
import { getWebhookWithSecret } from \"@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook\";
import { applyRateLimit } from \"@/modules/core/rate-limit/helpers\";
import { rateLimitConfigs } from \"@/modules/core/rate-limit/rate-limit-configs\";
import { createWebhook } from \"@/modules/integrations/webhooks/lib/webhook\";
import { withAuditLogging } from \"@/modules/ee/audit-logs/lib/handler\";

export const POST = withV3ApiWrapper({
  auth: \"session\",
  action: \"created\",
  targetType: \"webhook\",
  schemas: { params: ZId },
  handler: withAuditLogging(\"created\", \"webhook\", async ({ parsedInput, authentication, auditLog, ctx }) => {
    const webhookId = parsedInput.params.id;
    const workspaceId = await getWorkspaceIdFromWebhookId(webhookId);
    await authentication.assertCan({ type: \"user\", id: authentication.getUserId() }, \"workspace.write\", {
      type: \"workspace\",
      id: workspaceId,
    });

    const webhookResult = await getWebhookWithSecret(webhookId);
    if ("'!webhookResult.ok) {
      throw new Error("Webhook not found");
    }

    const original = webhookResult.data;
    const organizationId = await getOrganizationIdFromWebhookId(webhookId);
    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

    const newWebhook = await createWebhook(workspaceId, {
      name: original.name ? `Copy of ${original.name}` : null,
      url: original.url,
      source: original.source,
      triggers: original.triggers,
      surveyIds: original.surveyIds,
    });

    ctx.organizationId = organizationId;
    ctx.newObject = newWebhook;

    return { data: newWebhook };
  }),
});
ROUTE_EOF'

